from typing import List

MOD = 10**9 + 7

def countPathsWithXorValue(grid: List[List[int]], k: int) -> int:
    m, n = len(grid), len(grid[0])
    mx = max(max(row) for row in grid)
    size = 1 << mx.bit_length()  # every XOR of values <= mx is < size
    if k >= size:
        return 0

    prev = None  # DP row above: prev[j][x] = ways to reach (i-1, j) with XOR x
    for i in range(m):
        cur = [None] * n
        for j in range(n):
            v = grid[i][j]
            ways = [0] * size
            if i == 0 and j == 0:
                ways[v] = 1
            else:
                if i > 0:
                    up = prev[j]
                    for x in range(size):
                        if up[x]:
                            ways[x ^ v] += up[x]
                if j > 0:
                    left = cur[j - 1]
                    for x in range(size):
                        if left[x]:
                            ways[x ^ v] += left[x]
                for x in range(size):
                    ways[x] %= MOD
            cur[j] = ways
        prev = cur
    return prev[n - 1][k]
